const canvas = document.querySelector('canvas');
const ctx = canvas.getContext('2d');

function drawFlower(x, y, radius, petals) {
    for (let i = 0; i < petals; i++) {
        ctx.beginPath();
        ctx.arc(x, y, radius, (i * Math.PI) / 3, ((i + 1) * Math.PI) / 3);
        ctx.fill();
    }
}

drawFlower(100, 100, 20, 6);

